import {isEncryptionKeysValid} from '../../utils/service-worker-utils';

describe('test service-worker-utils', () => {

  it('should test isEncryptionKeysValid', () => {

    //Normal case should return true
    expect(isEncryptionKeysValid({
      activeKeyId: 'secretKey',
      keys: [
        {keyId: 'key-1', value: 'value-1'}
      ]
    })).toBe(true);

    expect(isEncryptionKeysValid({
      activeKeyId: 'secretKey',
      keys: [
        {keyId: 'key-1', value: 'value-1'},
        {keyId: 'key-2', value: 'value-2'},
      ]
    })).toBe(true);

    expect(isEncryptionKeysValid({
      activeKeyId: 'secretKey',
      keys: [
        {keyId: 'key-1', value: 'value-1'},
        {keyId: 'key-2', value: 'value-2'},
        {keyId: 'key-3', value: 'value-3'},
      ]
    })).toBe(true);

    //Undefined case
    expect(isEncryptionKeysValid(undefined)).toBe(false);

    //blank activeKeyId
    expect(isEncryptionKeysValid({
      activeKeyId: '',
      keys: [
        {keyId: 'key-1', value: 'value-1'}
      ]
    })).toBe(false);

    //undefined activeKeyId
    expect(isEncryptionKeysValid.call(undefined, {
      activeKeyId: undefined,
      keys: [
        {keyId: 'key-1', value: 'value-1'}
      ]
    })).toBe(false);

    //empty keys array
    expect(isEncryptionKeysValid.call(undefined, {
      activeKeyId: 'secretKey',
      keys: [
      ]
    })).toBe(false);

    //bad keys array
    expect(isEncryptionKeysValid.call(undefined, {
      activeKeyId: 'secretKey',
      keys: [
        {keyId: '', value: 'value-1'}
      ]
    })).toBe(false);

    expect(isEncryptionKeysValid.call(undefined, {
      activeKeyId: 'secretKey',
      keys: [
        {keyId: 'key-1', value: ''}
      ]
    })).toBe(false);

    expect(isEncryptionKeysValid.call(undefined, {
      activeKeyId: 'secretKey',
      keys: [
        {keyId: undefined, value: 'value-1'}
      ]
    })).toBe(false);

    expect(isEncryptionKeysValid.call(undefined, {
      activeKeyId: 'secretKey',
      keys: [
        {keyId: 'key-1', value: undefined}
      ]
    })).toBe(false);

    expect(isEncryptionKeysValid.call(undefined, {
      activeKeyId: 'secretKey',
      keys: [
        {keyId: undefined, value: 'value-1'},
        {keyId: 'key-2', value: 'value-2'},
        {keyId: '', value: 'value-3'},
        {keyId: 'key-4', value: ''},
        {keyId: 'key-5', value: 'value-5'},
        {keyId: 'key-6', value: undefined},
      ]
    })).toBe(false);
  });

});